const body = $input.item.json.body || {};
const CUSTOMER_ID = body.customer_id || 'demo-customer-001';
const CUSTOMER_NAME = body.customer_name || 'Demo Şirketi A.Ş.';
const CUSTOMER_EMAIL = body.customer_email || 'demo@talksfusion.com';

if (!CUSTOMER_ID?.trim()) {
  throw new Error('customer_id boş olamaz');
}

return [{
  json: {
    customer_id: CUSTOMER_ID,
    customer_name: CUSTOMER_NAME,
    customer_email: CUSTOMER_EMAIL,
    fileId: body.fileId
  }
}];

const ENDPOINT = 'https://unstructured.turklawai.com/general/v0/general';
const API_KEY = 'Y3CLuxVY9gVakedQwswGxsAMy8LoC7TE';

const bin = $input.item?.binary?.data;
if (!bin?.data) {
  throw new Error('Binary data yok');
}

const fileBuf = Buffer.from(bin.data, 'base64');
const fileName = bin.fileName || 'document.pdf';
const contentType = bin.mimeType || 'application/octet-stream';

const boundary = '----n8n-' + Math.random().toString(16).slice(2);
const CRLF = '\r\n';
const parts = [];

const pushText = (name, value) => {
  parts.push(Buffer.from(`--${boundary}${CRLF}Content-Disposition: form-data; name="${name}"${CRLF}${CRLF}${value}${CRLF}`));
};

parts.push(Buffer.from(`--${boundary}${CRLF}`));
parts.push(Buffer.from(`Content-Disposition: form-data; name="files"; filename="${fileName}"${CRLF}`));
parts.push(Buffer.from(`Content-Type: ${contentType}${CRLF}${CRLF}`));
parts.push(fileBuf);
parts.push(Buffer.from(CRLF));

pushText('strategy', 'auto');
pushText('coordinates', 'true');
pushText('split_documents', 'false');

parts.push(Buffer.from(`--${boundary}--${CRLF}`));
const body = Buffer.concat(parts);

const res = await this.helpers.httpRequest({
  method: 'POST',
  url: ENDPOINT,
  headers: {
    'unstructured-api-key': String(API_KEY).trim(),
    'Accept': 'application/json',
    'Content-Type': `multipart/form-data; boundary=${boundary}`,
    'Content-Length': body.length,
  },
  body,
});

let out = res;
if (typeof out === 'string') {
  try { out = JSON.parse(out); } catch { out = { raw: out }; }
} else if (Buffer.isBuffer?.(out)) {
  out = { raw: out.toString('utf8') };
}
if (Array.isArray(out)) {
  out = { elements: out, filename: fileName };
}

return { json: out };

const items = $input.all();
let els;

if (items.length === 1 && Array.isArray(items[0].json.elements)) {
  els = items[0].json.elements;
} else {
  els = items.map(i => i.json);
}

const out = [];
let cur = null;
let hasQA = false;

// Q/A pattern var mı kontrol et
for (const e of els) {
  const t = String(e.text || '').trim();
  if (/^Q[:\-]/i.test(t) || /^A[:\-]/i.test(t)) {
    hasQA = true;
    break;
  }
}

// Q/A formatı yoksa tüm elementi geçir
if (!hasQA) {
  return els.map(e => ({ json: e }));
}

// Q/A formatı varsa extraction yap
for (const e of els) {
  const t = String(e.text || '').trim();
  if (!t) continue;

  if (/^Q[:\-]/i.test(t)) {
    if (cur) out.push(cur);
    cur = { question: t.replace(/^Q[:\-]\s*/i, ''), answer: '' };
  } else if (/^A[:\-]/i.test(t)) {
    if (cur) {
      cur.answer = t.replace(/^A[:\-]\s*/i, '');
      out.push(cur);
      cur = null;
    }
  }
}

if (cur) out.push(cur);

return out.length > 0 ? out.map(x => ({ json: x })) : els.map(e => ({ json: e }));

const MAX_CHARS = 1800;
const OVERLAP = 200;

function fnv1a32(str, seed = 0x811c9dc5) {
  let h = seed >>> 0;
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = (h + (h << 1) + (h << 4) + (h << 7) + (h << 8) + (h << 24)) >>> 0;
  }
  return h >>> 0;
}

function fnv1a64Hex(str) {
  const h1 = fnv1a32(str, 0x811c9dc5);
  const h2 = fnv1a32(str + '|salt', 0x811c9dc5 ^ 0xABCDEF01);
  return h1.toString(16).padStart(8, '0') + h2.toString(16).padStart(8, '0');
}

const norm = s => String(s || '').trim().replace(/\s+/g, ' ');
const hashQA = (q, a) => fnv1a64Hex(norm(q) + '\n' + norm(a));
const hashText = (t) => fnv1a64Hex(norm(t));

function splitSentences(s) {
  return String(s).split(/(?<=[\.!?…])\s+/);
}

function chunkText(text, maxChars = MAX_CHARS, overlap = OVERLAP) {
  const sents = splitSentences(text);
  const chunks = [];
  let buf = '';
  let lastBreak = 0;

  for (let i = 0; i < sents.length; i++) {
    const next = buf ? buf + ' ' + sents[i] : sents[i];
    if (next.length <= maxChars) {
      buf = next;
      continue;
    }

    if (buf) chunks.push(buf.trim());

    let back = '';
    for (let j = i - 1; j >= lastBreak && back.length < overlap; j--) {
      back = sents[j] + ' ' + back;
    }
    buf = (back + sents[i]).trim();
    lastBreak = i;
  }

  if (buf) chunks.push(buf.trim());
  return chunks.length ? chunks : [text.slice(0, maxChars)];
}

const isHeading = t => /^(Title|Header|Heading|SectionHeader|H[1-6])$/i.test(String(t || ''));

const items = $input.all();
const looksLikeQA = items.some(it => it.json && (it.json.question || it.json.answer));
const filename = items[0]?.json?.filename || 'unknown.pdf';

if (looksLikeQA) {
  const out = [];
  items.forEach((it) => {
    const q = (it.json.question || '').trim();
    const a = (it.json.answer || '').trim();
    const base = q && a ? `Q: ${q}\nA: ${a}` : (q || a);
    if (!base) return;

    const pairId = hashQA(q, a);
    const chunks = base.length > MAX_CHARS ? chunkText(base) : [base];
    const meta = { filename, source: 'qa', ...it.json.metadata };

    chunks.forEach((text, ci) => {
      out.push({
        json: {
          id: `${pairId}-${ci}`,
          kind: 'qa',
          text,
          question: q || null,
          answer: a || null,
          chunk_index: ci,
          chunk_total: chunks.length,
          metadata: meta,
        },
      });
    });
  });
  return out;
}

let elements;
if (items.length === 1 && Array.isArray(items[0].json.elements)) {
  elements = items[0].json.elements;
} else if (items.length === 1 && typeof items[0].json.text === 'string') {
  elements = [{ text: items[0].json.text, type: 'Document' }];
} else {
  elements = items.map(i => i.json);
}

const out = [];
let sectionTitle = null;
let buffer = '';
let ids = [];

function flush() {
  const content = buffer.trim();
  if (!content) {
    buffer = '';
    ids = [];
    return;
  }

  const base = sectionTitle ? `${sectionTitle}\n\n${content}` : content;
  const chunks = base.length > MAX_CHARS ? chunkText(base) : [base];

  chunks.forEach((text, ci) => {
    const chunkId = hashText(text);
    out.push({
      json: {
        id: `${chunkId}-${ci}`,
        kind: 'document',
        title: sectionTitle || null,
        text,
        question: null,
        answer: null,
        chunk_index: ci,
        chunk_total: chunks.length,
        metadata: { filename, source: 'document', element_ids: ids.slice() },
      },
    });
  });

  buffer = '';
  ids = [];
}

for (const e of elements || []) {
  const t = String(e.text || '').trim();
  const typ = e.type || '';

  if (isHeading(typ)) {
    flush();
    sectionTitle = t || sectionTitle;
    continue;
  }

  if (!t) continue;

  const candidate = buffer ? buffer + '\n' + t : t;
  if (candidate.length > MAX_CHARS) {
    flush();
    buffer = t;
    ids = e.element_id ? [e.element_id] : [];
  } else {
    buffer = candidate;
    if (e.element_id) ids.push(e.element_id);
  }
}

flush();

return out.length ? out : [{ json: { id: 'empty', kind: 'empty', text: 'No content', metadata: {} } }];

const OPENAI_API_KEY = 'YOUR_OPENAI_API_KEY_HERE';
const MODEL = 'text-embedding-3-small';
const BATCH_SIZE = 64;
const API_URL = 'https://api.openai.com/v1/embeddings';

const sleep = ms => new Promise(r => setTimeout(r, ms));

async function embedBatch(inputs) {
  const body = { model: MODEL, input: inputs, encoding_format: 'float' };
  const options = {
    method: 'POST',
    uri: API_URL,
    headers: {
      Authorization: `Bearer ${OPENAI_API_KEY}`,
      'Content-Type': 'application/json',
    },
    body,
    json: true,
  };

  const maxRetries = 4;
  let attempt = 0;

  while (true) {
    try {
      const res = await this.helpers.request(options);
      if (!res?.data || !Array.isArray(res.data)) {
        throw new Error('Unexpected OpenAI response');
      }
      return res.data.map(d => d.embedding);
    } catch (e) {
      const status = e.statusCode || e.response?.statusCode;
      if ((status === 429 || status >= 500) && attempt < maxRetries) {
        await sleep(Math.min(2000 * (2 ** attempt), 12000));
        attempt++;
        continue;
      }
      throw new Error(`OpenAI embeddings failed (${status}): ${e.message}`);
    }
  }
}

const items = $input.all();
const out = items.map(i => ({ json: { ...i.json } }));

const todo = [];
for (let idx = 0; idx < items.length; idx++) {
  const j = items[idx].json || {};
  const txt = String(j.text || '').trim();
  if (!txt) continue;
  todo.push({ idx, id: j.id, text: txt });
}

if (todo.length === 0) return out;

for (let i = 0; i < todo.length; i += BATCH_SIZE) {
  const batch = todo.slice(i, i + BATCH_SIZE);
  const inputs = batch.map(b => b.text);
  const embeddings = await embedBatch.call(this, inputs);

  batch.forEach((b, k) => {
    const emb = embeddings[k];
    out[b.idx].json.embedding = emb;
    out[b.idx].json.embedding_dim = Array.isArray(emb) ? emb.length : 1536;
  });
}

return out;

const customerNode = $('Customer Bilgi').first();
const customerId = customerNode.json.customer_id;

return $input.all().map(i => {
  const j = i.json;
  return {
    json: {
      id: j.id,
      customer_id: customerId,
      kind: j.kind || 'document',
      text: j.text,
      question: j.question || null,
      answer: j.answer || null,
      embedding: j.embedding,
      embedding_dim: j.embedding_dim || 1536,
      metadata: j.metadata || {},
      chunk_index: j.chunk_index || 0,
      chunk_total: j.chunk_total || 1
    }
  };
});
